.missing-fields-form {
  min-height: 100dvh;
  width: 100%;
  display: flex;
  justify-content: center;
  background: black;
}

.missing-fields-form__scroll {
  width: 100%;
  max-width: 480px;
  padding: 2rem 1.25rem 3rem;
  overflow-y: auto;
  background: var(--farm-cream);
  border-left: 3px solid var(--farm-wood);
  border-right: 3px solid var(--farm-wood);
}

.missing-fields-form__header {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.35rem;
  margin-bottom: 1.75rem;
}

.brand-mark {
  width: 3.25rem;
  height: 3.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--farm-grass) 0%, var(--farm-accent-dark) 100%);
  margin-bottom: 0.5rem;
  box-shadow: 0 8px 24px -8px rgba(90, 158, 51, 0.6);
  border: 3px solid var(--farm-cream);
}

.brand-mark__icon {
  width: 1.75rem;
  height: 1.75rem;
  color: var(--farm-cream);
}

.brand-avatar {
  margin-bottom: 0.5rem;
  border: 2px solid var(--farm-accent);
}

.title {
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--farm-text-dark);
  margin: 0;
}

.subtitle {
  font-size: 0.85rem;
  line-height: 1.5;
  color: var(--farm-text-muted);
  margin: 0;
}

.missing-fields-form__body {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.gender-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.6rem;
}

.age-preview {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.85rem 1rem;
  border-radius: 0.75rem;
  background: var(--farm-cream-dark);
  border: 1px solid var(--farm-wood);
}

.age-preview__label {
  font-size: 0.78rem;
  color: var(--farm-text-muted);
}

.age-preview__value {
  font-weight: 700;
  color: var(--farm-text-dark);
  margin-left: auto;
}

.submit-error {
  font-size: 0.8rem;
  color: #b3441f;
  margin: -0.5rem 0 0;
  text-align: center;
}

.submit-button {
  font-weight: 600;
  margin-top: 0.25rem;
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}

.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
